import React, { forwardRef } from 'react'
import type { EventPayload } from '@gpuix/react'
import type { JSX } from '@gpuix/react/jsx-runtime'
import { toGpuixTheme, useTheme, type Style } from '@gpuix-ui/core'
import type { Instance } from '@gpuix-ui/primitives'
import { useFocusState } from './internal'

type HostTextareaProps = JSX.IntrinsicElements['textarea']

export interface TextareaProps extends Omit<HostTextareaProps, 'style' | 'onChange' | 'children'> {
  style?: Style
  textareaStyle?: Style
  onValueChange?: (value: string) => void
  onChange?: (event: EventPayload) => void
  disabled?: boolean
  /** Paint no border or background, for a composer that supplies its own frame. */
  unstyled?: boolean
  wrapperTestId?: string
}

export const Textarea = forwardRef<Instance, TextareaProps>(function Textarea(
  { style, textareaStyle, onValueChange, onChange, disabled = false, readOnly, unstyled = false, onFocus, onBlur, wrapperTestId, theme, minRows = 2, maxRows = 8, ...props },
  ref,
) {
  const t = useTheme()
  const focus = useFocusState({ onFocus, onBlur })
  return (
    <div
      testId={wrapperTestId}
      style={{
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        minWidth: 0,
        borderRadius: t.radius.md,
        borderWidth: unstyled ? 0 : 1,
        borderColor: focus.focused ? t.colors.ring : t.colors.input,
        backgroundColor: unstyled ? '#00000000' : t.colors.background,
        paddingLeft: unstyled ? 0 : 12,
        paddingRight: unstyled ? 0 : 12,
        paddingTop: unstyled ? 0 : 8,
        paddingBottom: unstyled ? 0 : 8,
        opacity: disabled ? 0.5 : 1,
        ...style,
      }}
    >
      <textarea
        {...props}
        ref={ref}
        minRows={minRows}
        maxRows={maxRows}
        readOnly={readOnly || disabled}
        theme={theme ?? toGpuixTheme(t)}
        onFocus={focus.onFocus}
        onBlur={focus.onBlur}
        onChange={(event) => {
          onChange?.(event)
          onValueChange?.(event.value ?? '')
        }}
        style={{
          width: '100%',
          minWidth: 0,
          fontFamily: t.font.sans,
          fontSize: t.font.size.base,
          lineHeight: t.font.lineHeight.base,
          color: t.colors.foreground,
          backgroundColor: '#00000000',
          borderWidth: 0,
          ...textareaStyle,
        }}
      />
    </div>
  )
})

/** Helpers shared by the styled components. */
import React, { useState, type ReactNode } from 'react'
import type { EventPayload } from '@gpuix/react'
import type { Style } from '@gpuix-ui/core'

/**
 * GPUI does not inherit `color`, so a bare string child would paint black.
 * Wrap string and number children in a `<text>` carrying the given style;
 * pass elements through untouched.
 */
export function asText(children: ReactNode, style: Style): ReactNode {
  if (children == null || typeof children === 'boolean') return null
  if (typeof children === 'string' || typeof children === 'number') return <text style={style}>{String(children)}</text>
  if (Array.isArray(children)) {
    if (children.every((child) => typeof child === 'string' || typeof child === 'number')) return <text style={style}>{children.join('')}</text>
    // Mixed children, like an icon next to a label: wrap just the strings.
    return children.map((child, index) =>
      typeof child === 'string' || typeof child === 'number' ? (
        <text key={`text-${index}`} style={style}>
          {String(child)}
        </text>
      ) : (
        child
      ),
    )
  }
  return children
}

/** Track native focus on an element, for a focus ring. */
export function useFocusState(handlers: { onFocus?: (event: EventPayload) => void; onBlur?: (event: EventPayload) => void } = {}) {
  const [focused, setFocused] = useState(false)
  return {
    focused,
    onFocus: (event: EventPayload) => {
      handlers.onFocus?.(event)
      setFocused(true)
    },
    onBlur: (event: EventPayload) => {
      handlers.onBlur?.(event)
      setFocused(false)
    },
  }
}

/** Track hover in React state, for components that render different children on hover. */
export function useHoverState() {
  const [hovered, setHovered] = useState(false)
  return { hovered, onMouseEnter: () => setHovered(true), onMouseLeave: () => setHovered(false) }
}
